INSERT INTO _upd VALUES ('10.2.2.1.5','old',NULL,'2013-09-14','[{"kind": "table", "caption": "표 5", "images": [], "table": {"rows": [[{"t": "종 류", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정격속도 45m/min 이하의 것", "r": 0, "c": 1, "rs": 1, "cs": 1}, {"t": "정격속도 45m/min 초과하는 것", "r": 0, "c": 2, "rs": 1, "cs": 1}], [{"t": "과 속 스위치", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "63m/min 이하에서 작동할 것", "r": 1, "c": 1, "rs": 1, "cs": 1}, {"t": "정격속도의 1.3배 이하에서 작동할 것", "r": 1, "c": 2, "rs": 1, "cs": 1}], [{"t": "캣 치", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "과속스위치가 떨어짐과 동시 또는 떨어진 후 작동하고 또한, 하강방향의 속도가 68m/min를 넘기 전에 작동할 것", "r": 2, "c": 1, "rs": 1, "cs": 1}, {"t": "과속스위치가 떨어진 후 작동하고 또한, 하강방향의 속도가 정격속도의 1.4배를 넘기 전에 작동할 것", "r": 2, "c": 2, "rs": 1, "cs": 1}]]}, "notes": "", "search": "표 5 종 류 정격속도 45m/min 이하의 것 정격속도 45m/min 초과하는 것 과 속 스위치 63m/min 이하에서 작동할 것 정격속도의 1.3배 이하에서 작동할 것 캣 치 과속스위치가 떨어짐과 동시 또는 떨어진 후 작동하고 또한, 하강방향의 속도가 68m/min를 넘기 전에 작동할 것 과속스위치가 떨어진 후 작동하고 또한, 하강방향의 속도가 정격속도의 1.4배를 넘기 전에 작동할 것"}]'::jsonb,'표 5 종 류 정격속도 45m/min 이하의 것 정격속도 45m/min 초과하는 것 과 속 스위치 63m/min 이하에서 작동할 것 정격속도의 1.3배 이하에서 작동할 것 캣 치 과속스위치가 떨어짐과 동시 또는 떨어진 후 작동하고 또한, 하강방향의 속도가 68m/min를 넘기 전에 작동할 것 과속스위치가 떨어진 후 작동하고 또한, 하강방향의 속도가 정격속도의 1.4배를 넘기 전에 작동할 것');
