INSERT INTO _upd VALUES ('17.2.8.1','current','2022-03-02',NULL,'[{"kind": "figure", "caption": "그림 28 - 소방구조용 엘리베이터의 알림표지", "images": ["e17281a_0.png"], "table": null, "notes": "", "search": "그림 28 - 소방구조용 엘리베이터의 알림표지 소방구조용 엘리베이터 알림표지"}, {"kind": "table", "caption": "", "images": [], "table": {"rows": [[{"t": "구 분", "r": 0, "c": 0, "rs": 1, "cs": 2}, {"t": "기 준", "r": 0, "c": 2, "rs": 1, "cs": 1}], [{"t": "색상", "r": 1, "c": 0, "rs": 2, "cs": 1}, {"t": "바탕", "r": 1, "c": 1, "rs": 1, "cs": 1}, {"t": "적색", "r": 1, "c": 2, "rs": 1, "cs": 1}], [{"t": "그림", "r": 2, "c": 1, "rs": 1, "cs": 1}, {"t": "흰색", "r": 2, "c": 2, "rs": 1, "cs": 1}], [{"t": "크기", "r": 3, "c": 0, "rs": 2, "cs": 1}, {"t": "카 조작 반", "r": 3, "c": 1, "rs": 1, "cs": 1}, {"t": "20 ㎜×20 ㎜", "r": 3, "c": 2, "rs": 1, "cs": 1}], [{"t": "승강장", "r": 4, "c": 1, "rs": 1, "cs": 1}, {"t": "100 ㎜×100 ㎜ 이상", "r": 4, "c": 2, "rs": 1, "cs": 1}]]}, "notes": "비고 출입구가 2개 있는 엘리베이터의 경우 소방구조용 운전으로 사용되는 카 조작반에 표시", "search": "구 분 기 준 색상 바탕 적색 그림 흰색 크기 카 조작 반 20 ㎜×20 ㎜ 승강장 100 ㎜×100 ㎜ 이상 비고 출입구가 2개 있는 엘리베이터의 경우 소방구조용 운전으로 사용되는 카 조작반에 표시"}]'::jsonb,'그림 28 - 소방구조용 엘리베이터의 알림표지 소방구조용 엘리베이터 알림표지
