INSERT INTO _upd VALUES ('13.3.8.2','old',NULL,'2007-09-09','[{"kind": "table", "caption": "표 8 (2004년 12월 1일부터 시행)", "images": [], "table": {"rows": [[{"t": "항 목", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정격하중의 100%의 하중을 실은 경우", "r": 0, "c": 1, "rs": 1, "cs": 1}, {"t": "정격하중의 110%의 하중을 실은 경우", "r": 0, "c": 2, "rs": 1, "cs": 1}], [{"t": "속 도", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "상승 및 하강때의 속도가 설계도면에 기재된 속도의 90% 이상 105% 이하", "r": 1, "c": 1, "rs": 1, "cs": 1}, {"t": "상승 및 하강때의 속도가 설계도면에 기재된 속도의 85% 이상 110% 이하", "r": 1, "c": 2, "rs": 1, "cs": 1}], [{"t": "전 류", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "전동기 정격전류치의 135% 이하", "r": 2, "c": 1, "rs": 1, "cs": 1}, {"t": "전동기 정격전류치의 140% 이하", "r": 2, "c": 2, "rs": 1, "cs": 1}], [{"t": "작동압력", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "설계치의 115% 이하", "r": 3, "c": 1, "rs": 1, "cs": 1}, {"t": "설계치의 120% 이하", "r": 3, "c": 2, "rs": 1, "cs": 1}]]}, "notes": "", "search": "표 8 (2004년 12월 1일부터 시행) 항 목 정격하중의 100%의 하중을 실은 경우 정격하중의 110%의 하중을 실은 경우 속 도 상승 및 하강때의 속도가 설계도면에 기재된 속도의 90% 이상 105% 이하 상승 및 하강때의 속도가 설계도면에 기재된 속도의 85% 이상 110% 이하 전 류 전동기 정격전류치의 135% 이하 전동기 정격전류치의 140% 이하 작동압력 설계치의 115% 이하 설계치의 120% 이하"}, {"kind": "table", "caption": "표 8 (2004년 12월 1일 전까지의 종전기준)", "images": [], "table": {"rows": [[{"t": "항 목", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "적재하중의 100%의 하중을 실은 경우", "r": 0, "c": 1, "rs": 1, "cs": 1}, {"t": "적재하중의 110%의 하중을 실은 경우", "r": 0, "c": 2, "rs": 1, "cs": 1}], [{"t": "속 도", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "상승 및 하강때의 속도가 설계도면에 기재된 속도의 90% 이상 105% 이하", "r": 1, "c": 1, "rs": 1, "cs": 1}, {"t": "상승 및 하강때의 속도가 설계도면에 기재된 속도의 85% 이상 110% 이하", "r": 1, "c": 2, "rs": 1, "cs": 1}], [{"t": "전 류", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "전동기 정격전류치의 135% 이하", "r": 2, "c": 1, "rs": 1, "cs": 1}, {"t": "전동기 정격전류치의 140% 이하", "r": 2, "c": 2, "rs": 1, "cs": 1}], [{"t": "작동압력", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "설계치의 115% 이하", "r": 3, "c": 1, "rs": 1, "cs": 1}, {"t": "설계치의 120% 이하", "r": 3, "c": 2, "rs": 1, "cs": 1}